use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{fs,path::Path};
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn save(p:impl AsRef<Path>,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap()}
fn main(){let r=Path::new("/tmp/zopro-single-epoch-advancer");let source=r.join("advance_gate.rs");for p in [r.join("candidate/vendor/crossbeam-epoch/src/advance_gate.rs"),r.join("overlay/vendor/crossbeam-epoch/src/advance_gate.rs")]{fs::copy(&source,p).unwrap();}
 let mut pins=read(r.join("source-pins.json"));for p in [&source,&r.join("candidate/vendor/crossbeam-epoch/src/advance_gate.rs"),&r.join("repair.rs")]{pins[p.display().to_string()]=json!(format!("{:x}",Sha256::digest(fs::read(p).unwrap())));}save(r.join("source-pins.json"),&pins);
 let mut plan:Value=serde_json::from_str(&fs::read_to_string(r.join("native-plan.json")).unwrap().replace("/native/","/native-qualified/")).unwrap();let s=&mut plan["steps"][0];s["name"]=json!("epoch-repaired-test");let a=s["argv"].as_array_mut().unwrap();let i=a.iter().position(|v|v=="--").unwrap();a.insert(i,json!("internal::advance_gate::tests::held_permit_skips_and_release_allows_advancement"));a.push(json!("--exact"));s["unfiltered"]=json!(false);s["required_tests"]=json!(["internal::advance_gate::tests::held_permit_skips_and_release_allows_advancement"]);save(r.join("native-qualified-plan.json"),&plan);
 save(r.join("test-repair.json"),&json!({"problem":"The first h.pin() can collect and advance once, so asserting another successor while that same guard remained pinned was incorrect.","repair":"Acquire the test permit before pinning, making its initial automatic advance skip. Rename test to describe only advancement.","production_code_changed":false,"43_already_passing_epoch_tests_repeated":false,"test_result_qualification":"43 passed in original suite, repaired test runs separately; all44 covered across two invocations","preserved":["advance_gate-v1.rs","source-pins-v1.json","native-plan.json","native/epoch-tests/stdout.log","native/epoch-tests/stderr.log"]}));println!("Repaired test setup only; retained43passes, targeted missing check then rest of native workflow");}
